mapper.select:
SELECT * FROM ( select 'erro' as erroOrInfo, SALER_REW_PENA_NO as salerRewPenaNo, null as salerInstCode, SALER_INS_NO as salerInsNo, SALER_REW_PENA_TYEP as salerRewPenaTyep, null as salerRewPenaName, null as salerRewPenaComments, SALER_REW_PENA_INST as salerRewPenaInst, null as salerRewPenaInstName, SALER_REW_PENA_START as salerRewPenaStart, null as salerRewPenaEnd, null as salerComplainDetail, null as salerComplainResult, SALER_COMPLAIN_DATE as salerComplainDate, 'A' as dataStatus, to_char(ERR_MSG) as errMsg from CHB_SALER_REW_PENA_ERRODATA where 1=1
and SALER_INS_NO like concat(concat('%',#{salerInsNo,jdbcType=VARCHAR}),'%')
and SALER_REW_PENA_TYEP = #{salerRewPenaTyep,jdbcType=VARCHAR}
and SALER_REW_PENA_INST = #{salerRewPenaInst,jdbcType=VARCHAR}
and to_char(SALER_REW_PENA_START,'yyyy-MM-dd') >= #{searchSalerRewPenaStartStart,jdbcType=VARCHAR}
and to_char(SALER_REW_PENA_START,'yyyy-MM-dd') <= #{searchSalerRewPenaStartEnd,jdbcType=VARCHAR}
and to_char(SALER_COMPLAIN_DATE,'yyyy-MM-dd') >= #{searchSalerComplainDateStart,jdbcType=VARCHAR}
and to_char(SALER_COMPLAIN_DATE,'yyyy-MM-dd') <= #{searchSalerComplainDateEnd,jdbcType=VARCHAR}
UNION ALL
select 'info' as erroOrInfo, SALER_REW_PENA_NO as salerRewPenaNo, SALER_INST_CODE as salerInstCode, SALER_INS_NO as salerInsNo, SALER_REW_PENA_TYEP as salerRewPenaTyep, SALER_REW_PENA_NAME as salerRewPenaName, SALER_REW_PENA_COMMENTS as salerRewPenaComments, SALER_REW_PENA_INST as salerRewPenaInst, SALER_REW_PENA_INST_NAME as salerRewPenaInstName, SALER_REW_PENA_START as salerRewPenaStart, SALER_REW_PENA_END as salerRewPenaEnd, SALER_COMPLAIN_DETAIL as salerComplainDetail, SALER_COMPLAIN_RESULT as salerComplainResult, SALER_COMPLAIN_DATE as salerComplainDate, STATUS as dataStatus, null as errMsg from CHB_SALER_REW_PENA_INFO where 1=1
and SALER_INS_NO like concat(concat('%',#{salerInsNo,jdbcType=VARCHAR}),'%')
and SALER_REW_PENA_TYEP = #{salerRewPenaTyep,jdbcType=VARCHAR}
and SALER_REW_PENA_INST = #{salerRewPenaInst,jdbcType=VARCHAR}
and to_char(SALER_REW_PENA_START,'yyyy-MM-dd') >= #{searchSalerRewPenaStartStart,jdbcType=VARCHAR}
and to_char(SALER_REW_PENA_START,'yyyy-MM-dd') <= #{searchSalerRewPenaStartEnd,jdbcType=VARCHAR}
and to_char(SALER_COMPLAIN_DATE,'yyyy-MM-dd') >= #{searchSalerComplainDateStart,jdbcType=VARCHAR}
and to_char(SALER_COMPLAIN_DATE,'yyyy-MM-dd') <= #{searchSalerComplainDateEnd,jdbcType=VARCHAR}
) ORDER BY dataStatus DESC

select REGIST_BANK_CODE from CHB_ORG_REGIST_BANK_CODE
where
ORG_CODE = #{orgCode,jdbcType=VARCHAR}

select SALER_NAME from CHB_SALER_IDEN_INFO
where
SALER_INS_NO = #{salerInsNo,jdbcType=VARCHAR}

select count(SALER_INS_NO) from CHB_SALER_IDEN_INFO
where SALER_INS_NO = #{salerInsNo,jdbcType=VARCHAR}
and STATUS = 'E'
